// Confere somente o formato da resposta do login antes de alterar a credencial compartilhada.
// O token em si não é devolvido para logs, notas ou outros fluxos por este node.
// O endpoint documentado entrega accessToken, refreshToken e expiraEmSegundos.
const sessao = $('Fazer login técnico no CRM').first().json;
const variaveis = $('Variaveis renovacao JWT').first().json;

if (!sessao.accessToken || typeof sessao.accessToken !== 'string') {
  throw new Error('O CRM não retornou accessToken no login técnico.');
}

const expiraEmSegundos = Number(sessao.expiraEmSegundos ?? 0);
if (!Number.isFinite(expiraEmSegundos) || expiraEmSegundos <= 0) {
  throw new Error('O CRM não retornou expiraEmSegundos válido.');
}

const proximaRenovacaoEmMinutos = Number(variaveis.proxima_renovacao_em_minutos);
if (!Number.isFinite(proximaRenovacaoEmMinutos) || proximaRenovacaoEmMinutos <= 0) {
  throw new Error('PROXIMA_RENOVACAO_EM_MINUTOS_NAO_CONFIGURADA');
}

return [{
  json: {
    renovado: true,
    expira_em_segundos: expiraEmSegundos,
    proxima_renovacao_em_minutos: proximaRenovacaoEmMinutos
  }
}];

// Resultado seguro para acompanhamento: não inclui access token, refresh token, senha ou API key.
const validacao = $('Validar resposta do login').first().json;

return [{
  json: {
    sucesso: true,
    mensagem: 'Credencial Bearer do CRM atualizada.',
    expira_em_segundos: validacao.expira_em_segundos,
    proxima_renovacao_em_minutos: validacao.proxima_renovacao_em_minutos
  }
}];
